package com.happy.cinemaframe;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;
import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.locks.*;

/** Receiver-owned incremental index. Every network result/checkpoint survives restart. */
final class TrackIndex {
 interface Progress {void update(String message);}
 interface Rejection {boolean blocked(JSONObject track,String style);}
 boolean verifiedAlbum(String movie,String album)throws Exception{try(Cursor c=db.rawQuery("SELECT album FROM films WHERE id=?",new String[]{movie})){return c.moveToFirst()&&!c.isNull(0)&&album.equals(new JSONObject(c.getString(0)).optString("id"));}}
 final Context context;final SQLiteDatabase db;final SpotifySearch spotify;final SharedPreferences settings;
 final ReentrantLock work=new ReentrantLock(true);final JSONObject dictionary;
 volatile String message="색인 설정 대기",error="";private long lastNetwork=0,lastGemini=0;
 TrackIndex(Context c,SpotifySearch s)throws Exception{
  context=c;spotify=s;settings=c.getSharedPreferences("track_index",0);db=c.openOrCreateDatabase("track-index.db",0,null);
  db.execSQL("CREATE TABLE IF NOT EXISTS films(id TEXT PRIMARY KEY,payload TEXT,at INTEGER DEFAULT 0,album TEXT)");
  db.execSQL("CREATE TABLE IF NOT EXISTS tracks(k TEXT PRIMARY KEY,movie TEXT,rank INTEGER,isrc TEXT,payload TEXT,judged INTEGER DEFAULT 0)");
  db.execSQL("CREATE TABLE IF NOT EXISTS cache(k TEXT PRIMARY KEY,at INTEGER,payload TEXT)");db.execSQL("CREATE TABLE IF NOT EXISTS misses(movie TEXT PRIMARY KEY,at INTEGER,reason TEXT)");db.execSQL("CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,payload TEXT)");
  boolean hasSource=false;try(Cursor cinfo=db.rawQuery("PRAGMA table_info(cache)",null)){while(cinfo.moveToNext())if(cinfo.getString(1).equals("source"))hasSource=true;}if(!hasSource)db.execSQL("ALTER TABLE cache ADD COLUMN source TEXT");db.execSQL("UPDATE cache SET at=0 WHERE source IS NULL");
  // Production countries are evidence, not the requested Wikidata P495 mapping.
  try(Cursor pending=db.rawQuery("SELECT id,payload FROM films WHERE payload LIKE ?",new String[]{"%TMDB production_countries%"})){while(pending.moveToNext()){JSONObject m=new JSONObject(pending.getString(1));m.put("production_countries_evidence",m.optJSONArray("countries")).put("countries",new JSONArray()).put("country_source","Wikidata not yet mapped");db.execSQL("UPDATE films SET payload=? WHERE id=?",new Object[]{m.toString(),pending.getString(0)});}}
  dictionary=new JSONObject(new String(FrameCore.read(c.getAssets().open("music-tags.json"),100000),"UTF-8"));
  // Earlier builds applied Spotify's wait to all providers. Preserve Spotify's own
  // persisted Retry-After, but migrate that unrelated index-wide wait away.
  if(spotify.retryAt()>System.currentTimeMillis())try(Cursor errors=db.rawQuery("SELECT payload FROM audit ORDER BY id DESC LIMIT 20",null)){while(errors.moveToNext()){JSONObject event=new JSONObject(errors.getString(0));if(event.optString("kind").equals("maintenance_error")){if(event.optString("error").startsWith("Spotify"))settings.edit().putLong("retry_at",0).apply();break;}}}
 }
 void seed(JSONArray films)throws Exception{db.beginTransaction();try{for(int i=0;i<films.length();i++){JSONObject m=films.getJSONObject(i);db.execSQL("INSERT OR IGNORE INTO films(id,payload) VALUES(?,?)",new Object[]{m.getString("id"),m.toString()});}db.setTransactionSuccessful();}finally{db.endTransaction();}}
 void configure(JSONObject in)throws Exception{SharedPreferences.Editor e=settings.edit();for(String name:Arrays.asList("gemini","lastfm","tmdb"))if(in.has(name)){String key=in.getString(name).trim();if(key.length()<20||key.length()>4096)throw new IOException("Invalid "+name+" key");e.putString(name,key);}e.putBoolean("enabled",in.optBoolean("enabled",true)).apply();error="";}
 boolean configured(){return !settings.getString("gemini","").isEmpty()&&!settings.getString("lastfm","").isEmpty()&&!settings.getString("tmdb","").isEmpty();}
 JSONObject status()throws Exception{return new JSONObject().put("configured",configured()).put("enabled",settings.getBoolean("enabled",false)).put("busy",work.isLocked()).put("rules","strict-2026-11-08").put("last_tick_at",settings.getLong("last_tick",0)).put("misses",count("misses","")).put("retry_at",settings.getLong("retry_at",0)).put("spotify_retry_at",spotify.retryAt()).put("message",message).put("error",error).put("films",count("films","")).put("tracks",count("tracks","")).put("judged_fresh",count("tracks"," WHERE judged>"+(System.currentTimeMillis()-OstPolicy.TTL))).put("cycle_started_at",settings.getLong("cycle",0)).put("movies_this_cycle",settings.getInt("movie_count",0)).put("batches_this_cycle",settings.getInt("batch_count",0));}
 private int count(String table,String where){try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM "+table+where,null)){c.moveToFirst();return c.getInt(0);}}
 void log(String kind,JSONObject value)throws Exception{value.put("kind",kind).put("at",System.currentTimeMillis());db.execSQL("INSERT INTO audit(payload) VALUES(?)",new Object[]{value.toString()});db.execSQL("DELETE FROM audit WHERE id < (SELECT MAX(id)-1000 FROM audit)");}
 JSONArray audit()throws Exception{JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT payload FROM audit ORDER BY id DESC LIMIT 100",null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}
 private String hash(String text)throws Exception{byte[] a=MessageDigest.getInstance("SHA-256").digest(text.getBytes("UTF-8"));StringBuilder b=new StringBuilder();for(byte x:a)b.append(String.format("%02x",x&255));return b.toString();}
 private JSONObject cached(String key)throws Exception{try(Cursor c=db.rawQuery("SELECT at,payload FROM cache WHERE k=?",new String[]{key})){if(c.moveToFirst()){long age=System.currentTimeMillis()-c.getLong(0);if(age>=0&&age<OstPolicy.TTL)return new JSONObject(c.getString(1));}}return null;}
 private void cache(String key,JSONObject value,String source){db.execSQL("INSERT OR REPLACE INTO cache(k,at,payload,source) VALUES(?,?,?,?)",new Object[]{key,System.currentTimeMillis(),value.toString(),source});}
 private void pace()throws Exception{long wait=1000-(System.currentTimeMillis()-lastNetwork);if(wait>0)Thread.sleep(wait);lastNetwork=System.currentTimeMillis();}
 private JSONObject get(String provider,String path)throws Exception{
  String digest=hash(provider+":"+path);JSONObject old=cached(digest);if(old!=null)return old;
  pace();String url,credential=settings.getString(provider,"");
  if(provider.equals("deezer"))url="https://api.deezer.com/"+path;
  else if(provider.equals("tmdb"))url="https://api.themoviedb.org/3/"+path+(credential.startsWith("eyJ")?"":(path.contains("?")?"&":"?")+"api_key="+enc(credential));
  else url="https://ws.audioscrobbler.com/2.0/?format=json&"+path+"&api_key="+enc(credential);
  HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(20000);if(provider.equals("tmdb")&&credential.startsWith("eyJ"))c.setRequestProperty("Authorization","Bearer "+credential);
  try{int status=c.getResponseCode();if(status!=200){if(status==429){long delay=60000;try{delay=Math.max(delay,Long.parseLong(c.getHeaderField("Retry-After"))*1000);}catch(Exception ignored){}settings.edit().putLong("retry_at",System.currentTimeMillis()+delay).apply();}throw new IOException(provider+" HTTP "+status);}JSONObject data=new JSONObject(new String(FrameCore.read(c.getInputStream(),4000000),"UTF-8"));
   if(data.has("error")){if(provider.equals("deezer")&&data.optJSONObject("error")!=null&&data.getJSONObject("error").optInt("code")==800){cache(digest,data,provider);return data;}if(provider.equals("lastfm")&&data.optInt("error")==6){cache(digest,data,provider);return data;}throw new IOException(provider+" API error");}
   cache(digest,data,provider);return data;
  }finally{c.disconnect();}
 }
 private static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 private JSONArray searchAlbums(String q)throws Exception{String k=hash("spotify-albums:"+q);JSONObject c=cached(k);if(c!=null)return c.getJSONArray("items");pace();JSONArray a=spotify.searchAlbums(q,0);cache(k,new JSONObject().put("items",a),"Spotify Web API albums");return a;}
 private JSONObject album(String id)throws Exception{String k=hash("spotify-album:"+id);JSONObject c=cached(k);if(c!=null)return c;pace();JSONObject a=spotify.albumDetails(id);cache(k,a,"Spotify Web API album");return a;}
 private static String norm(String s){return AlbumIdentity.norm(s);}
 private static boolean titleMatch(JSONObject movie,String title){return AlbumIdentity.title(movie,title);}
 private static boolean credit(String artist,List<String> names){String a=norm(artist.replaceFirst("(?i)^the\\s+",""));for(String name:names){String b=norm(name.replaceFirst("(?i)^the\\s+",""));if(a.equals(b)||(b.length()>=8&&a.contains(b)))return true;}return false;}
 private JSONObject tmdbFilm(JSONObject movie)throws Exception{JSONArray found=get("tmdb","find/"+movie.getString("id")+"?external_source=imdb_id").getJSONArray("movie_results");if(found.length()!=1)throw new IOException("TMDB IMDb movie is not unique");return get("tmdb","movie/"+found.getJSONObject(0).getInt("id")+"?append_to_response=credits,external_ids");}
 private JSONArray albumTracks(String id)throws Exception{JSONArray all=new JSONArray();for(int offset=0;;offset+=100){JSONObject page=get("deezer","album/"+id+"/tracks?limit=100&index="+offset);JSONArray items=page.getJSONArray("data");for(int i=0;i<items.length();i++){JSONObject t=items.getJSONObject(i);if(!t.has("rank")||!t.has("isrc"))t=get("deezer","track/"+t.optString("id"));if(!(t.opt("rank") instanceof Number))throw new IOException("Deezer rank missing");all.put(t);}if(!page.has("next"))break;}return all;}
 private boolean resolve(JSONObject movie)throws Exception{
  message="OST 색인 · "+movie.optString("title");JSONObject tm=tmdbFilm(movie);JSONArray crew=tm.getJSONObject("credits").getJSONArray("crew");List<String> names=new ArrayList<>();
  for(int i=0;i<crew.length();i++){JSONObject c=crew.getJSONObject(i);if(c.optString("job").equals("Original Music Composer")){names.add(c.getString("name"));JSONArray aliases=get("tmdb","person/"+c.getInt("id")).optJSONArray("also_known_as");if(aliases!=null)for(int j=0;j<aliases.length();j++)names.add(aliases.getString(j));}}
  JSONObject selected=null;String source="";List<String> queries=new ArrayList<>();for(String title:new LinkedHashSet<>(Arrays.asList(movie.optString("title"),movie.optString("originalTitle"),tm.optString("title"))))if(!title.isEmpty())queries.add("album:\""+title.replace("\"","")+"\"");
  if(!names.isEmpty())for(String query:queries){JSONArray hits=searchAlbums(query);for(int i=0;i<hits.length();i++){JSONObject h=hits.getJSONObject(i);if(!titleMatch(movie,h.optString("name")))continue;boolean match=false,various=false;JSONArray artists=h.getJSONArray("artists");for(int j=0;j<artists.length();j++){String n=artists.getJSONObject(j).getString("name");match|=credit(n,names);various|=n.equalsIgnoreCase("Various Artists");}if(!match&&!various)continue;
    JSONObject full=album(h.getString("id"));if(!match&&various){JSONArray ts=full.getJSONObject("tracks").getJSONArray("items");for(int n=0;n<ts.length();n++){JSONArray aa=ts.getJSONObject(n).getJSONArray("artists");for(int j=0;j<aa.length();j++)match|=credit(aa.getJSONObject(j).getString("name"),names);}}if(!match)continue;
    String upc=full.optJSONObject("external_ids")==null?"":full.getJSONObject("external_ids").optString("upc");if(upc.isEmpty())continue;JSONObject dz=get("deezer","album/upc:"+upc);if(dz.has("error")||!AlbumIdentity.release(movie,full,dz)||!titleMatch(movie,dz.optString("title"))||!dz.optString("upc").replaceFirst("^0+","").equals(upc.replaceFirst("^0+","")))continue;
    String date=dz.optString("release_date");if(date.length()>=4&&Integer.parseInt(date.substring(0,4))<movie.optInt("year")-1)continue;selected=dz;source="Spotify album + credited composer + exact UPC";break;}if(selected!=null)break;}
  if(selected==null&&!names.isEmpty()){JSONArray hits=get("deezer","search/album?q="+enc(movie.optString("originalTitle",movie.getString("title"))+" soundtrack")+"&limit=100").getJSONArray("data");for(int i=0;i<hits.length();i++){JSONObject h=hits.getJSONObject(i);if(DeezerOst.albumMatches(movie,h.optString("title"))&&titleMatch(movie,h.optString("title"))&&credit(h.getJSONObject("artist").optString("name"),names)){JSONObject detail=get("deezer","album/"+h.optString("id"));if(detail.optString("record_type").equals("single"))continue;selected=detail;source="Deezer exact title + credited composer";break;}}}
  if(selected==null){db.execSQL("INSERT OR REPLACE INTO misses VALUES(?,?,?)",new Object[]{movie.getString("id"),System.currentTimeMillis(),names.isEmpty()?"missing_composer_credit":"no_verified_album"});db.execSQL("UPDATE films SET at=? WHERE id=?",new Object[]{System.currentTimeMillis(),movie.getString("id")});log("album_not_verified",new JSONObject().put("movie_id",movie.getString("id")).put("reason",names.isEmpty()?"missing_composer_credit":"no_verified_album"));return false;}
  JSONArray raw=albumTracks(selected.optString("id")),tracks=new JSONArray();for(int i=0;i<raw.length();i++){JSONObject t=raw.getJSONObject(i);tracks.put(new JSONObject().put("id",t.optString("id")).put("title",t.getString("title")).put("artist",t.getJSONObject("artist").optString("name")).put("rank",t.get("rank")).put("isrc",t.optString("isrc")).put("album_id",selected.optString("id")).put("fetched_at",System.currentTimeMillis()));}
  importRecord(new JSONObject().put("movie",movie).put("album",selected).put("tracks",tracks).put("credited_composers",new JSONArray(names)).put("method",source).put("fetched_at",System.currentTimeMillis()));return true;
 }
 void importRecord(JSONObject record)throws Exception{JSONObject movie=record.getJSONObject("movie");String id=movie.getString("id");JSONArray ts=record.optJSONArray("tracks");if(!record.has("album")){long at=record.getLong("fetched_at");db.execSQL("INSERT OR REPLACE INTO misses VALUES(?,?,?)",new Object[]{id,at,record.optString("reason","no_verified_album")});db.execSQL("UPDATE films SET at=? WHERE id=?",new Object[]{at,id});return;}long now=record.optLong("fetched_at");if(now<=0)throw new IOException("Index import requires actual fetched_at");db.beginTransaction();try{
  db.execSQL("DELETE FROM misses WHERE movie=?",new Object[]{id});db.execSQL("INSERT OR REPLACE INTO films VALUES(?,?,?,?)",new Object[]{id,movie.toString(),now,record.getJSONObject("album").toString()});Set<String> present=new HashSet<>();
  for(int i=0;i<ts.length();i++){JSONObject t=new JSONObject(ts.getJSONObject(i).toString());String k=id+":"+t.optString("id");present.add(k);t.put("key",k).put("movie_id",id).put("movie_title",movie.getString("title")).put("composers",record.optJSONArray("credited_composers")==null?new JSONArray():record.getJSONArray("credited_composers"));
   long judged=0;JSONObject decision=t.optJSONObject("gemini");if(decision!=null&&decision.has("confidence"))judged=decision.optLong("fetched_at");else t.remove("gemini");
   try(Cursor cur=db.rawQuery("SELECT payload,judged FROM tracks WHERE k=?",new String[]{k})){if(cur.moveToFirst()){JSONObject old=new JSONObject(cur.getString(0));if(judged==0&&old.optString("isrc").equals(t.optString("isrc"))&&old.optString("title").equals(t.optString("title"))&&old.has("gemini")){t.put("gemini",old.getJSONObject("gemini"));judged=cur.getLong(1);}}}
   db.execSQL("INSERT OR REPLACE INTO tracks VALUES(?,?,?,?,?,?)",new Object[]{k,id,t.getInt("rank"),t.optString("isrc"),t.toString(),judged});
  }
  List<String> remove=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT k FROM tracks WHERE movie=?",new String[]{id})){while(c.moveToNext())if(!present.contains(c.getString(0)))remove.add(c.getString(0));}for(String k:remove)db.execSQL("DELETE FROM tracks WHERE k=?",new Object[]{k});db.setTransactionSuccessful();
 }finally{db.endTransaction();}}
 private JSONArray tags(String kind,String artist,String title)throws Exception{String path="method="+kind+".getTopTags&artist="+enc(artist)+"&autocorrect=0"+(kind.equals("track")?"&track="+enc(title):"");JSONObject data=get("lastfm",path);JSONArray tags=data.optJSONObject("toptags")==null?null:data.getJSONObject("toptags").optJSONArray("tag");return tags==null?new JSONArray():tags;}
 private Map<String,JSONObject> movies()throws Exception{Map<String,JSONObject> out=new LinkedHashMap<>();try(Cursor c=db.rawQuery("SELECT id,payload FROM films",null)){while(c.moveToNext())out.put(c.getString(0),new JSONObject(c.getString(1)));}return out;}
 private int judgeBatch(JSONObject profile)throws Exception{
  Map<String,JSONObject> films=movies();List<JSONObject> pending=new ArrayList<>();long now=System.currentTimeMillis();
  try(Cursor c=db.rawQuery("SELECT payload FROM tracks WHERE judged<? ORDER BY rank DESC",new String[]{String.valueOf(now-OstPolicy.TTL)})){while(c.moveToNext()){JSONObject t=new JSONObject(c.getString(0));JSONObject m=films.get(t.optString("movie_id"));if(m!=null&&now-t.optLong("fetched_at")<OstPolicy.TTL&&(profile==null||OstPolicy.eligible(m,profile)))pending.add(t);}}
  // Prioritize supporting artist evidence only for investigation, never acceptance.
  if(profile!=null&&!profile.optString("music_style").isEmpty()){String wanted=profile.optString("music_style");pending.sort((a,b)->Boolean.compare(hint(b,wanted),hint(a,wanted)));}
  if(pending.isEmpty())return 0;List<JSONObject> chosen=pending.subList(0,Math.min(50,pending.size()));JSONArray input=new JSONArray();
  for(JSONObject t:chosen){JSONArray artist=t.optJSONArray("artist_tags"),track=t.optJSONArray("track_tags");if(artist==null||track==null||now-t.optLong("tags_fetched_at")>=OstPolicy.TTL){artist=tags("artist",t.optString("artist"),"");track=tags("track",t.optString("artist"),t.optString("title"));t.put("artist_tags",artist).put("track_tags",track).put("tags_fetched_at",System.currentTimeMillis());db.execSQL("UPDATE tracks SET payload=? WHERE k=?",new Object[]{t.toString(),t.getString("key")});}JSONArray five=new JSONArray();for(int i=0;i<Math.min(5,artist.length());i++)five.put(artist.get(i));
   input.put(new JSONObject().put("key",t.getString("key")).put("title",t.getString("title")).put("movie",t.getString("movie_title")).put("artist",t.optString("artist")).put("composers",t.optJSONArray("composers")).put("artist_top5_tags",five).put("track_tags",track));}
  message="Gemini 판단 · "+input.length()+"곡";long delay=15000-(System.currentTimeMillis()-lastGemini);if(delay>0)Thread.sleep(delay);lastGemini=System.currentTimeMillis();Map<String,JSONObject> decisions=GeminiJudge.judge(input,settings.getString("gemini",""),dictionary);
  db.beginTransaction();try{for(JSONObject t:chosen){JSONObject d=decisions.get(t.getString("key"));t.put("gemini",d);db.execSQL("UPDATE tracks SET payload=?,judged=? WHERE k=?",new Object[]{t.toString(),d.getLong("fetched_at"),t.getString("key")});}db.setTransactionSuccessful();}finally{db.endTransaction();}
  log("gemini_batch",new JSONObject().put("source","Gemini 판단").put("count",input.length()).put("decisions",new JSONArray(decisions.values())));return input.length();
 }
 private boolean hint(JSONObject t,String style){JSONArray tags=t.optJSONArray("artist_tags"),names=new JSONArray();if(tags!=null)for(int i=0;i<Math.min(5,tags.length());i++)names.put(tags.optJSONObject(i)==null?tags.optString(i):tags.optJSONObject(i).optString("name"));return IndexRules.styleMatches(names,style,dictionary);}
 private List<JSONObject> matches(JSONObject profile,Rejection rejected)throws Exception{
  Map<String,JSONObject> films=movies();Map<String,List<JSONObject>> grouped=new LinkedHashMap<>();long now=System.currentTimeMillis();
  try(Cursor c=db.rawQuery("SELECT payload FROM tracks WHERE judged>? ORDER BY rank DESC",new String[]{String.valueOf(now-OstPolicy.TTL)})){while(c.moveToNext()){JSONObject t=new JSONObject(c.getString(0)),m=films.get(t.optString("movie_id"));if(m==null||now-t.optLong("fetched_at")>=OstPolicy.TTL||t.optLong("fetched_at")>now||!OstPolicy.eligible(m,profile)||!IndexRules.accepts(t,profile,dictionary,now)||rejected.blocked(t,profile.optString("music_style")))continue;List<JSONObject> list=grouped.computeIfAbsent(m.optString("id"),k->new ArrayList<>());if(list.size()<3)list.add(t);}}
  List<JSONObject> result=new ArrayList<>();List<String> ids=new ArrayList<>(grouped.keySet());ids.sort((a,b)->Double.compare(films.get(b).optDouble("rating"),films.get(a).optDouble("rating")));
  for(int n=0;n<3;n++)for(String id:ids)if(grouped.get(id).size()>n)result.add(new JSONObject().put("movie",films.get(id)).put("track",grouped.get(id).get(n)));return result;
 }
 List<JSONObject> plan(JSONObject profile,Progress progress,Rejection rejected)throws Exception{
  if(System.currentTimeMillis()<settings.getLong("retry_at",0))throw new IOException("API 재시도 대기 중");if(!configured())throw new IOException("Gemini·Last.fm·TMDB 색인 연결이 필요합니다");progress.update("색인 확인 · 더 찾는 중");work.lock();try{error="";List<JSONObject> candidates=matches(profile,rejected);
   for(int i=0;i<4&&candidates.size()<20;i++){progress.update("더 찾는 중 · Gemini 판단 "+(i+1)+" / 4");int n=judgeBatch(profile);if(n==0){int added=0;for(JSONObject m:unindexed(profile,4)){resolve(m);added++;}if(added==0)break;n=judgeBatch(profile);if(n==0)break;}candidates=matches(profile,rejected);}
   List<JSONObject> plan=new ArrayList<>();Set<String> uris=new HashSet<>();for(JSONObject row:candidates){progress.update("Spotify ISRC 확인 · "+plan.size()+"곡");JSONObject t=row.getJSONObject("track");String isrc=t.optString("isrc");if(!isrc.matches("[A-Za-z]{2}[A-Za-z0-9]{3}[0-9]{7}"))continue;String k=hash("spotify-isrc:"+isrc);JSONObject cached=cached(k);JSONArray hits;if(cached==null){pace();hits=spotify.searchTracks("isrc:"+isrc,0);cache(k,new JSONObject().put("items",hits),"Spotify Web API exact ISRC search");}else hits=cached.getJSONArray("items");JSONObject hit=OstPolicy.spotifyMatch(hits,isrc);if(hit==null){log("spotify_skip",new JSONObject().put("isrc",isrc).put("reason","no_exact_playable_isrc"));continue;}if(!uris.add(hit.getString("uri")))continue;
    t=new JSONObject(t.toString()).put("uri",hit.getString("uri")).put("duration",hit.getLong("duration_ms")).put("spotify_checked_at",System.currentTimeMillis()).put("album_source","Gemini 판단 · Deezer 순위");row.put("track",t).put("reason",t.getJSONObject("gemini").getString("reason")).put("selection","Gemini 판단 · Deezer 순위").put("album_source","Gemini 판단 · Deezer 순위").put("album_url","https://www.deezer.com/album/"+t.optString("album_id"));plan.add(row);if(plan.size()>=60)break;}
   message="색인 선곡 "+plan.size()+"곡";log("request_plan",new JSONObject().put("profile",profile).put("tracks",new JSONArray(plan)).put("investigation_cap","4 batches of at most 50, up to 16 additional movies; unresolved/low excluded"));return plan;
  }catch(Exception e){error=e.getMessage();log("request_error",new JSONObject().put("error",error));throw e;}finally{work.unlock();}
 }
 private List<JSONObject> unindexed(JSONObject profile,int limit)throws Exception{List<JSONObject> out=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT at,payload FROM films WHERE at<? OR id IN (SELECT movie FROM misses WHERE at<?) ORDER BY at ASC",new String[]{String.valueOf(System.currentTimeMillis()-OstPolicy.TTL),String.valueOf(System.currentTimeMillis()-86400000L)})){while(c.moveToNext()){JSONObject m=new JSONObject(c.getString(1)).put("index_checked_at",c.getLong(0));if(profile==null||OstPolicy.eligible(m,profile))out.add(m);}}out.sort(Comparator.comparingLong((JSONObject m)->m.optLong("index_checked_at")).thenComparing(Comparator.comparingInt((JSONObject m)->m.optInt("votes")).reversed()));return out.subList(0,Math.min(limit,out.size()));}
 private void supply()throws Exception{int page=settings.getInt("supply_page",1),period=settings.getInt("period",1980);String[] paths={"movie/popular?page="+page,"movie/now_playing?page="+page,"discover/movie?sort_by=popularity.desc&primary_release_date.gte="+period+"-01-01&primary_release_date.lte="+(period+9)+"-12-31&page="+page};
  for(String path:paths){JSONArray results=get("tmdb",path).getJSONArray("results");for(int i=0;i<results.length();i++){JSONObject shortMovie=results.getJSONObject(i);JSONObject m=get("tmdb","movie/"+shortMovie.getInt("id")+"?append_to_response=external_ids");String id=m.optString("imdb_id");if(!id.matches("tt[0-9]+"))continue;try(Cursor c=db.rawQuery("SELECT 1 FROM films WHERE id=?",new String[]{id})){if(c.moveToFirst())continue;}String date=m.optString("release_date");if(date.length()<4)continue;JSONArray countries=new JSONArray(),genres=new JSONArray(),cs=m.optJSONArray("production_countries"),gs=m.optJSONArray("genres");if(cs!=null)for(int j=0;j<cs.length();j++)countries.put(cs.getJSONObject(j).optString("iso_3166_1"));if(gs!=null)for(int j=0;j<gs.length();j++){String name=gs.getJSONObject(j).getString("name");genres.put(name.equals("Science Fiction")?"Sci-Fi":name);}
   JSONObject film=new JSONObject().put("id",id).put("title",m.getString("title")).put("originalTitle",m.optString("original_title",m.getString("title"))).put("year",Integer.parseInt(date.substring(0,4))).put("rating",m.optDouble("vote_average")).put("votes",m.optInt("vote_count")).put("rating_source","TMDB").put("genres",genres).put("countries",new JSONArray()).put("production_countries_evidence",countries).put("country_source","Wikidata not yet mapped").put("poster_url",m.optString("poster_path").isEmpty()?"":"https://image.tmdb.org/t/p/original"+m.optString("poster_path"));seed(new JSONArray().put(film));}}
  settings.edit().putInt("supply_page",page>=5?1:page+1).putInt("period",period>=2020?1930:period+10).putLong("supply_at",System.currentTimeMillis()).apply();
 }
 void maintenance(){settings.edit().putLong("last_tick",System.currentTimeMillis()).apply();if(!configured()||!settings.getBoolean("enabled",false)||System.currentTimeMillis()<settings.getLong("retry_at",0)||!work.tryLock())return;try{
  long now=System.currentTimeMillis(),cycle=settings.getLong("cycle",0);if(now-cycle>=86400000L)settings.edit().putLong("cycle",now).putInt("movie_count",0).putInt("batch_count",0).apply();
  if(now-settings.getLong("supply_at",0)>=86400000L){message="TMDB 신작·인기·시대별 영화 갱신";supply();return;}
  int n=settings.getInt("movie_count",0);if(n<80&&System.currentTimeMillis()>=spotify.retryAt()){JSONObject retry=null;try(Cursor c=db.rawQuery("SELECT f.payload FROM films f JOIN misses m ON f.id=m.movie WHERE m.at<? ORDER BY m.at LIMIT 1",new String[]{String.valueOf(now-86400000L)})){if(c.moveToFirst())retry=new JSONObject(c.getString(0));}if(retry!=null)resolve(retry);else{List<JSONObject> list=unindexed(null,1);if(!list.isEmpty())resolve(list.get(0));}settings.edit().putInt("movie_count",n+1).apply();}
  int batches=settings.getInt("batch_count",0);if(batches<20){judgeBatch(null);settings.edit().putInt("batch_count",batches+1).apply();}error="";message="매일 갱신 · 체크포인트 저장됨";
 }catch(Exception e){error=e.getMessage();settings.edit().putLong("retry_at",Math.max(settings.getLong("retry_at",0),System.currentTimeMillis()+3600000)).apply();try{log("maintenance_error",new JSONObject().put("error",error));}catch(Exception ignored){}}finally{work.unlock();}}
}
